struct Node {
    int data;
    Node* next;
    Node(int val) : data(val), next(nullptr) {}
};

struct Queue {
    Node* front;
    Node* rear;
    Queue() : front(nullptr), rear(nullptr) {}
};

void enqueue(Queue& q, int value) {
    Node* newNode = new Node(value);
    if (q.rear == nullptr) {
        q.front = q.rear = newNode;
    } else {
        q.rear->next = newNode;
        q.rear = newNode;
    }
}

int dequeue(Queue& q) {
    if (q.front == nullptr) {
        throw std::runtime_error("Queue underflow");
    }
    Node* temp = q.front;
    int value = temp->data;
    q.front = q.front->next;
    if (q.front == nullptr) {
        q.rear = nullptr;
    }
    delete temp;
    return value;
}

